function runStage(body,media,title,text,extra=''){const stage=el('section',null,'exp-stage'+(extra?' '+extra:'')),frame=el('div',null,'exp-stage-media'),copy=el('div',null,'exp-stage-copy'),actions=el('div',null,'exp-stage-actions');if(media)frame.append(media);if(title)copy.append(el('b',title));if(text)copy.append(paragraph(text));append(stage,frame,copy,actions);body.append(stage);return {stage,actions,copy};}
function stageArt(src){if(!src)return null;const picture=img(src,'','exp-stage-art exp-event-art');picture.onerror=()=>picture.remove();return picture;}
// The enemy on the layer background with its name and HP over the bottom of the picture. done paints a finished fight.
// A won fight fades the defeated enemy out of the picture (user 2026-10-24); the background stays.
// The fight's own art node is kept for its result: a reward-zone guardian's win leaves the zone, and a defeat ends the run,
// so rebuilding the art then would fall back to another background (user 2026-10-24).
function fightArea(e,done){const sw=done?done.swarm:swarmSnap(s.battle),area=el('div',null,'enemyarea exp-fight'+(done?' impact-active':'')+(done?.win?' exp-fight-won':'')+(sw?' exp-swarm':''));area.id='combatMonsterArea';if(sw)area.setAttribute('data-swarm',sw.length);area.append(sw?swarmArt(sw):done?.art||combatArt(e));if(sw)paintSwarm(area,sw,done?-1:s.battle.queue[0]?.slot);const effects=el('div');effects.id='battleEffects';area.append(effects);
 const info=el('div',null,'combat-enemy-info exp-fight-info'),hp=el('p'),track=el('div',null,'combat-hp-track'),fill=el('span');hp.id='combatEnemyHP';fill.id='combatEnemyBar';track.setAttribute('aria-hidden','true');track.append(fill);if(!done){const lines=el('div',null,'exp-fight-lines'),status=paragraph('','exp-fight-status'),counter=paragraph('','exp-fight-status'),boost=paragraph('','exp-fight-boost');status.id='combatStatus';counter.id='combatKillCount';boost.id='combatFoeBoost';boost.hidden=true;append(lines,status,counter);info.append(lines,boost);}append(info,el('h3',done&&sw?[...new Set(sw.map(x=>C.enemies[x.id].name))].join('・'):e.name),hp,track);area.append(info);
 if(done){const left=done.win?0n:N(done.hp??e.hp),max=N(e.hp);hp.textContent='生命力 '+F(left)+' / '+F(e.hp)+(done.win?' · 撃破':'');if(sw&&done.win)hp.textContent=sw.length+'体撃破';fill.style.width=(max>0n?Math.min(100,Number(left*10000n/max)/100):0)+'%';const burst=el('div',null,'damage-burst'+(done.win?' finishing-hit':''));append(burst,el('strong',done.win?(done.oneHit?'一撃撃破':'撃破'):'敗北'));if(lastStrike&&lastStrike.target===e.id&&paintedStrike!==strikeSequence&&Date.now()-lastStrikeAt<800){paintedStrike=strikeSequence;paintHits(effects,lastStrike,'');}effects.append(burst);}
 return area;}
// Swarm (user 2026-11-11: 群敌一次出现三只、一场打完): every member stands side by side on the layer background, left to
// right as they are fought, each with its own HP bar; the one being attacked has a ring at its feet, a fallen one fades.
function swarmSnap(b){if(!b?.run||!Array.isArray(b.group)||!Array.isArray(b.queue))return null;return b.group.map((id,i)=>{const q=b.queue.find(q=>q.slot===i),f=q?B.foe({...b,queue:[q]},id):C.enemies[id];return {id,hp:q?String(q.hp??0):'0',max:String(f?.hp??1)};});}
function swarmArt(sw){const frame=el('div',null,'combat-art-frame swarm-frame'),run=XR.run(s),bgSrc=run?XR.layer(run).background?.src:null;frame.setAttribute('data-layered','true');
 if(bgSrc){const bg=img(bgSrc,'','combat-background');bg.setAttribute('aria-hidden','true');bg.onerror=()=>{bg.hidden=true;};frame.append(bg);}
 const row=el('div',null,'swarm-row');row.style.gridTemplateColumns='repeat('+sw.length+',1fr)';
 sw.forEach((x,i)=>{const e=C.enemies[x.id],pic=e.scene||e.art||{},slot=el('div',null,'swarm-slot'),src=pic.combatForegroundSrc||pic.src;slot.setAttribute('data-swarm-slot',String(i));
  if(src){const fg=img(src,e.name,'swarm-foreground');fg.onerror=()=>{fg.hidden=true;slot.append(el('span',e.name,'combat-art-placeholder'));};slot.append(fg);}else slot.append(el('span',e.name,'combat-art-placeholder'));
  const track=el('div',null,'swarm-hp'),fill=el('span');track.setAttribute('aria-hidden','true');track.append(fill);slot.append(track);row.append(slot);});
 frame.append(row);return frame;}
function swarmSlots(area){return area?[...area.querySelectorAll('[data-swarm-slot]')]:[];}
const swarmPart=(slot,c)=>[...(slot?.children||[])].find(n=>String(n.className||'').split(' ').includes(c));
function paintSwarm(area,sw,target){if(!area||!sw)return;swarmSlots(area).forEach((slot,i)=>{const x=sw[i];if(!x)return;const hp=N(x.hp),max=N(x.max),fill=swarmPart(slot,'swarm-hp')?.children?.[0];if(fill)fill.style.width=(max>0n?Math.max(0,Math.min(100,Number(hp*10000n/max)/100)):0)+'%';slot.classList.toggle('swarm-fallen',hp===0n);slot.classList.toggle('swarm-target',hp>0n&&i===target);});}
// Members that struck back this action lunge one after another, after Alice's hits.
function swarmLunge(area,strike,after){const order=(strike?.events||[]).filter(e=>e?.kind==='strike'&&Number.isInteger(e.foe)).map(e=>e.foe),slots=swarmSlots(area);order.forEach((k,i)=>{const slot=slots[k];if(!slot)return;slot.classList.remove('swarm-lunge');void slot.offsetWidth;slot.style.animationDelay=(after+i*160)+'ms';slot.classList.add('swarm-lunge');});}
// Damage numbers (user 2026-11-03): every damage packet of one action pops its own "-N" over the enemy, one after
// another, and the enemy flashes and shakes once per packet (at most HIT_MAX). Purely visual; nothing is saved.
const HIT_GAP_MS=120,HIT_MAX=6,HIT_STRONG=['opening','periodic','burst','item-periodic','current-hp'],HIT_X=[0,-20,20,-12,12,0],HIT_Y=[46,38,38,54,54,62];
function strikeHits(strike){const list=(strike?.events||[]).filter(e=>e&&e.kind!=='strike'&&N(e.damage)>0n).map(e=>({kind:e.kind,damage:N(e.damage),...(Number.isInteger(e.foe)?{foe:e.foe}:{})}));if(!list.length&&N(strike?.damageDealt)>0n)list.push({kind:'normal',damage:N(strike.damageDealt)});
 if(list.length>HIT_MAX){const cut=list.splice(HIT_MAX-1),rest=cut.reduce((a,h)=>a+h.damage,0n);list.push({kind:'normal',damage:rest,...(Number.isInteger(cut.at(-1).foe)?{foe:cut.at(-1).foe}:{})});}return list;}
function recoil(strike){const area=$('combatMonsterArea'),slot=area?.classList.contains('exp-swarm')?strikeHits(strike)[0]?.foe:null,target=Number.isInteger(slot)?swarmPart(swarmSlots(area)[slot],'swarm-foreground'):$('combatForeground');if(!target)return;const n=Math.max(1,strikeHits(strike).length);target.style.animationName=strikeSequence%2?'enemy-recoil-a':'enemy-recoil-b';target.style.animationDuration=(n>1?HIT_GAP_MS/1000:.18)+'s';target.style.animationIterationCount=String(n);target.style.animationTimingFunction='ease-out';}
function paintHits(box,strike,label){if(!box||!strike)return;for(const c of [...box.children])if(!String(c.className||'').includes('damage-float'))c.remove();
 const hits=strikeHits(strike);hits.forEach((h,i)=>{const n=el('span',null,'damage-float'+(HIT_STRONG.includes(h.kind)?' damage-float-strong':h.kind==='extra'?' damage-float-light':''));n.setAttribute('data-value','-'+F(h.damage));n.setAttribute('aria-hidden','true');n.setAttribute('data-strike',strikeSequence);
  const n_=Number($('combatMonsterArea')?.getAttribute('data-swarm'))||0,x=Number.isInteger(h.foe)&&n_>1?((h.foe+.5)/n_*100-50)+HIT_X[i%HIT_X.length]/4:HIT_X[i%HIT_X.length]+(strikeSequence%3-1)*3;n.style.left='calc(50% + '+x+'%)';n.style.top=HIT_Y[i%HIT_Y.length]+'%';n.style.animationDelay=(i*HIT_GAP_MS)+'ms';n.addEventListener('animationend',()=>n.remove());box.append(n);});
 const floats=[...box.children];for(let i=0;i<floats.length-12;i++)floats[i].remove();
 if(label){const burst=el('div',null,'damage-burst finishing-hit');burst.setAttribute('data-strike',strikeSequence);burst.append(el('strong',label));burst.style.animationDelay=(Math.max(0,hits.length-1)*HIT_GAP_MS)+'ms';box.append(burst);}}
// While a run's last view waits before the village, the page keeps the exploration layout.
function runHolding(){return !!combatHold?.stage&&Date.now()<combatHold.until;}
function leaveRun(){if(leaving)return;advanceNow();leaving={until:Date.now()+LEAVE_MS};const body=$('sceneBody');body.classList.add('exp-leaving');for(const b of body.querySelectorAll('button')){b.disabled=true;if(String(b.className||'').includes('exp-back')&&b.style.visibility!=='hidden')b.textContent=baseWord()+'へ戻る…';}}
