function warmReachableAssets(ahead=false){if(!globalThis.GameAssets?.preload)return Promise.resolve();const out=imagePaths(C.characters[s.active]);if(memoryUnlocked())out.add('assets/alice.png');for(const t of Object.values(C.stories)){if(t.retired||t.campaignChapter>1||C.characters[t.owner]?.chapter>1)continue;const form=R.storyForm(t.key)||s.active;if(!s.owned[form]||!R.canPlayStory({...s,active:form},t.key))continue;for(const path of storyImages(t,form))out.add(path);}for(const id of C.dungeonOrder)if(R.dungeonOpen(s,id)){imagePaths(C.dungeons[id],out);if(C.explorations?.[id])explorationImages(id,out,ahead);else for(const enemy of C.dungeons[id].enemies)imagePaths(C.enemies[enemy],out);}imagePaths(C.explorationIcons||{},out);for(const id of EXPLORATION_ICON_CATEGORIES.categories)out.add('assets/exploration/categories/'+id+'.webp');return GameAssets.preload([...out],{once:true});}
function scheduleAssetWarm(){const ready=globalThis.GamePresentationReady;if(!ready)return;const key=[s.active,s.view,s.dungeon,Object.keys(s.owned).join(','),Object.keys(s.completedStories).join(','),Object.keys(s.bosses).join(','),C.dungeonOrder.map(id=>C.explorations?.[id]?clearedLayers(id):'').join(',')].join('|');if(key===assetWarmKey)return;assetWarmKey=key;ready.then(()=>warmReachableAssets(true)).catch(()=>{assetWarmKey='';});}
function playStory(key,done=null,replay=false){if(memoryActive())return;const t=C.stories[key];if(!t||(!replay&&s.seen[key])){if(done)done();return;}if(story||preparingStory||!R.canPlayStory(s,key))return;if(!globalThis.GameAssets?.preload){openPreparedStory(key,done,replay);return;}advanceNow();preparingStory={key};notice='画像を読み込み中…';render();const appearance=R.storyForm(key)||'alice';GameAssets.preload(storyImages(visibleStory(t),appearance)).then(()=>{preparingStory=null;notice='';lastAt=Date.now();openPreparedStory(key,done,replay);},()=>{preparingStory=null;lastAt=Date.now();storyRetryAfter=Date.now()+5000;notice='画像を読み込めませんでした。通信を確認して、もう一度開いてください。';render();});}
// Lines marked ifOwned/unlessOwned (academy completion, T8) follow who has been devoured (ifOwned may list several ids: all must be devoured); ifMet/unlessMet follow whose
