function pendingCandidates(){return Object.values(C.stories).filter(t=>!t.retired&&!s.seen[t.key]&&!['guild','forge','evolution'].includes(t.id)&&!['encounter','assault','devour','phase'].includes(R.storyPhase(t))&&(R.storyUsesFixedForm(t.key)||t.source==='chapter'&&(t.campaignChapter||['finale','hidden_finale','covenant','mine_0','mine_1','mine','road_0','road_1','road','ruins_0','ruins_1','ruins'].includes(t.id))));}
