function pendingStory(){if(memoryActive()||story||preparingStory||Date.now()<storyRetryAfter||s.view==='combat'||s.view==='encounter'||s.view==='run'||['collectionDialog','growthDialog','dungeons','characterDialog','bestiaryDialog','storyLibrary','chestResultDialog','devourResultDialog','bossSkillDialog','shopNoticeDialog','chapterClearDialog','portraitZoom'].some(id=>$(id).open))return;const next=pendingCandidates().find(t=>R.storyAvailable(s,t.key));if(next)playStory(next.key);}
